    const lt = stored(LIKE_T, {});
    if (on && (name || album)) {
      const t = { id: k, name: name || (album && album.name) || "未命名", artists: artists || [], album: album || {}, duration: duration || 0 };
      lt[k] = t; remember([t]);
    } else if (!on && lt[k]) delete lt[k];
