    const items = (stored(INDEX_KEY, { items: [] }).items || []);
    const core = query.replace(/[《》\s]/g, "").toLowerCase();
    return items.filter((it) => it.name.replace(/\s/g, "").toLowerCase().indexOf(core) >= 0).slice(0, 6).map((it) => it.name);
